const rows = [{id:3},{id:7},{id:11},{id:14},{id:21},{id:28},{id:35}];
const LIMIT = 3;
function page(cursor){
  const slice = rows.filter(r => cursor === null || r.id > cursor).slice(0, LIMIT);
  const next = slice.length === LIMIT ? slice[slice.length - 1].id : null;
  return { ids: slice.map(r => r.id), next };
}
let cursor = null;
let n = 0;
while (true) {
  const { ids, next } = page(cursor);
  if (ids.length === 0) break;
  n++;
  console.log('page ' + n + ': [' + ids.join(',') + '] next=' + next);
  if (next === null) break;
  cursor = next;
}
